enum Value: Hashable, Comparable {
    case integer(Int), symbol(String)
    static func < (a: Value, b: Value) -> Bool {
        switch (a, b) {
        case let (.integer(x), .integer(y)):
            return x < y
        case (.integer, .symbol):
            return true
        case (.symbol, .integer):
            return false
        case let (.symbol(x), .symbol(y)):
            return x < y
        }
    }
    var text: String {
        switch self {
        case let .integer(n):
            return String(n)
